(function(){const page=window.location.pathname.split("/").pop().replace(".html","");if(page==="takbeer")return;if(document.getElementById("tasbih-fab"))return;const style=document.createElement("style");style.textContent=`\n    #tasbih-fab {\n      position: fixed;\n      bottom: 88px;\n      left: 20px;\n      z-index: 900;\n      width: 56px;\n      height: 56px;\n      border-radius: 50%;\n      background: linear-gradient(135deg, #0e3b2e, #1a5d47);\n      color: #fff;\n      font-size: 24px;\n      border: none;\n      cursor: pointer;\n      box-shadow: 0 4px 16px rgba(14,59,46,.35);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      text-decoration: none;\n      transition: transform .2s, box-shadow .2s;\n      -webkit-tap-highlight-color: transparent;\n    }\n    #tasbih-fab:hover  { transform: scale(1.08); box-shadow: 0 6px 22px rgba(14,59,46,.45); }\n    #tasbih-fab:active { transform: scale(.93); }\n\n    #tasbih-fab-tip {\n      position: fixed;\n      bottom: 154px;\n      left: 12px;\n      z-index: 901;\n      background: var(--card, #fff);\n      color: var(--ink, #222);\n      border: 1px solid var(--border, #e0e0e0);\n      border-radius: 12px;\n      padding: 6px 12px;\n      font-size: 12px;\n      font-weight: 700;\n      box-shadow: 0 4px 14px rgba(0,0,0,.12);\n      white-space: nowrap;\n      opacity: 0;\n      transform: translateY(6px);\n      transition: opacity .25s, transform .25s;\n      pointer-events: none;\n    }\n    #tasbih-fab-tip.show { opacity: 1; transform: translateY(0); }\n  `;document.head.appendChild(style);const fab=document.createElement("a");fab.id="tasbih-fab";fab.href="takbeer.html";fab.setAttribute("aria-label","المسبحة");fab.textContent="📿";document.body.appendChild(fab);const SEEN_KEY="zad_tasbih_fab_seen";if(!localStorage.getItem(SEEN_KEY)){const tip=document.createElement("div");tip.id="tasbih-fab-tip";tip.textContent="المسبحة";document.body.appendChild(tip);requestAnimationFrame(()=>{setTimeout(()=>tip.classList.add("show"),600);setTimeout(()=>{tip.classList.remove("show");setTimeout(()=>tip.remove(),300);localStorage.setItem(SEEN_KEY,"1")},3e3)})}})();